const REQUEST_LINE_PATTERN = /^([^ ]+) +([^ ]+) +[^ ]+$/;
const HEADER_LINE_PATTERN = /^([!#$%&'*+.^_`|~0-9A-Za-z-]+):[ \t]*(.*?)[ \t]*$/;
const CONTENT_LENGTH_PATTERN = /^\d+$/;
const HEADER_END = '\r\n\r\n';

// Parses the request line and headers (the text before the blank line).
// Returns { request } with method, target, headers (lowercased names) and
// contentLength, or { error: true } if the head is malformed.
const parseHead = (head) => {
  const [requestLine, ...headerLines] = head.split('\r\n');
  const requestLineMatch = REQUEST_LINE_PATTERN.exec(requestLine);
  if (!requestLineMatch) return { error: true };

  const headers = {};
  for (const line of headerLines) {
    const headerMatch = HEADER_LINE_PATTERN.exec(line);
    if (!headerMatch) return { error: true };
    const name = headerMatch[1].toLowerCase();
    const value = headerMatch[2];
    if (name === 'content-length' && name in headers && headers[name] !== value) {
      return { error: true };
    }
    headers[name] = name in headers && name !== 'content-length' ? `${headers[name]}, ${value}` : value;
  }

  if ('transfer-encoding' in headers) return { error: true };

  let contentLength = 0;
  if ('content-length' in headers) {
    if (!CONTENT_LENGTH_PATTERN.test(headers['content-length'])) return { error: true };
    contentLength = Number(headers['content-length']);
    if (!Number.isSafeInteger(contentLength)) return { error: true };
  }

  const [, method, target] = requestLineMatch;
  return { request: { method, target, headers, contentLength } };
};

module.exports = { HEADER_END, parseHead };

const ROOT_TARGET = '/';
const ECHO_PATH = '/echo';
const USER_POST_TARGET_PATTERN = /^\/users\/([^/]+)\/posts\/([^/]+)$/;

const buildResponse = (status, { headers = [], body = '' } = {}) =>
  [
    `HTTP/1.1 ${status}`,
    ...headers,
    `Content-Length: ${Buffer.byteLength(body, 'latin1')}`,
    'Connection: close',
    '',
    body,
  ].join('\r\n');

const OK_RESPONSE = buildResponse('200 OK');
const BAD_REQUEST_RESPONSE = buildResponse('400 Bad Request');
const NOT_FOUND_RESPONSE = buildResponse('404 Not Found');
const PAYLOAD_TOO_LARGE_RESPONSE = buildResponse('413 Payload Too Large');
const METHOD_NOT_ALLOWED_RESPONSE = buildResponse('405 Method Not Allowed', {
  headers: ['Allow: GET'],
});

const routeRequest = ({ method, target }) => {
  const path = target.split('?')[0];
  if (path === ECHO_PATH) {
    return buildResponse('200 OK', {
      headers: ['Content-Type: text/plain'],
      body: `${method} ${path}`,
    });
  }

  const userPostMatch = USER_POST_TARGET_PATTERN.exec(target);
  if (target !== ROOT_TARGET && !userPostMatch) return NOT_FOUND_RESPONSE;
  if (method !== 'GET') return METHOD_NOT_ALLOWED_RESPONSE;
  if (!userPostMatch) return OK_RESPONSE;

  const [, userId, postId] = userPostMatch;
  return buildResponse('200 OK', {
    headers: ['Content-Type: text/plain'],
    body: `${userId} ${postId}`,
  });
};

module.exports = { BAD_REQUEST_RESPONSE, PAYLOAD_TOO_LARGE_RESPONSE, routeRequest };

const net = require('net');
const { BAD_REQUEST_RESPONSE, PAYLOAD_TOO_LARGE_RESPONSE, routeRequest } = require('./router');
const { HEADER_END, parseHead } = require('./request');

const PORT = process.env.PORT || 8080;
const DEFAULT_MAX_REQUEST_LINE_BYTES = 8192;
const MAX_HEADER_BYTES = 65536;
const MAX_BODY_BYTES = 1024 * 1024;
const REQUEST_LINE_END = '\r\n';

const readMaxRequestLineBytes = () => {
  const configuredValue = process.env.MAX_REQUEST_LINE_BYTES ?? DEFAULT_MAX_REQUEST_LINE_BYTES;
  const maxRequestLineBytes = Number(configuredValue);
  if (!Number.isSafeInteger(maxRequestLineBytes) || maxRequestLineBytes <= 0) {
    throw new Error(`MAX_REQUEST_LINE_BYTES must be a positive integer, got "${configuredValue}"`);
  }
  return maxRequestLineBytes;
};

const MAX_REQUEST_LINE_BYTES = readMaxRequestLineBytes();

const hasRequestLine = (receivedBytes) =>
  receivedBytes.subarray(0, MAX_REQUEST_LINE_BYTES).indexOf(REQUEST_LINE_END) !== -1;

const server = net.createServer((conn) => {
  let receivedBytes = Buffer.alloc(0);
  let request = null;
  let bodyStart = 0;

  const sendResponse = (response) => conn.end(response, 'latin1');

  conn.on('error', () => {});
  conn.on('data', (chunk) => {
    if (conn.writableEnded) return;
    receivedBytes = Buffer.concat([receivedBytes, chunk]);

    if (!request) {
      if (!hasRequestLine(receivedBytes) && receivedBytes.length >= MAX_REQUEST_LINE_BYTES) {
        return sendResponse(BAD_REQUEST_RESPONSE);
      }

      const headEnd = receivedBytes.indexOf(HEADER_END);
      if (headEnd === -1) {
        if (receivedBytes.length > MAX_HEADER_BYTES) sendResponse(BAD_REQUEST_RESPONSE);
        return;
      }
      if (headEnd > MAX_HEADER_BYTES) return sendResponse(BAD_REQUEST_RESPONSE);

      const parsed = parseHead(receivedBytes.toString('latin1', 0, headEnd));
      if (parsed.error) return sendResponse(BAD_REQUEST_RESPONSE);
      if (parsed.request.contentLength > MAX_BODY_BYTES) {
        return sendResponse(PAYLOAD_TOO_LARGE_RESPONSE);
      }
      request = parsed.request;
      bodyStart = headEnd + HEADER_END.length;
    }

    if (receivedBytes.length - bodyStart >= request.contentLength) {
      request.body = receivedBytes.subarray(bodyStart, bodyStart + request.contentLength);
      sendResponse(routeRequest(request));
    }
  });
  conn.on('end', () => {
    if (!conn.writableEnded) sendResponse(BAD_REQUEST_RESPONSE);
  });
});

server.listen(PORT);
